#!/usr/bin/env node
// Creates all new backend files for the Admin Module.
// Run from the project root: interview-coach-ai-main/
// Safe to re-run — writes are idempotent (same content = no-op).
import fs from 'fs';
import path from 'path';

const files = {
  "backend/controllers/adminAlertsController.js": "import * as adminAlertsService from '../services/adminAlerts.service.js';\n\nexport const getAlerts = async (req, res, next) => {\n  try {\n    const alerts = await adminAlertsService.getAlerts();\n    res.json({ success: true, alerts });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { getAlerts };\n",
  "backend/controllers/adminAnalyticsController.js": "import { getSupabase } from '../config/supabase.js';\n\nfunction average(nums) {\n  const valid = nums.filter((n) => typeof n === 'number' && !Number.isNaN(n));\n  if (valid.length === 0) return 0;\n  return Math.round((valid.reduce((a, b) => a + b, 0) / valid.length) * 10) / 10;\n}\n\nfunction tallyTopN(arraysOfStrings, n = 10) {\n  const counts = new Map();\n  for (const arr of arraysOfStrings) {\n    for (const item of arr || []) {\n      if (!item) continue;\n      counts.set(item, (counts.get(item) || 0) + 1);\n    }\n  }\n  return [...counts.entries()]\n    .sort((a, b) => b[1] - a[1])\n    .slice(0, n)\n    .map(([label, count]) => ({ label, count }));\n}\n\nexport const getAnalytics = async (req, res, next) => {\n  try {\n    const sb = getSupabase();\n    const [{ data: scoreRows, error: e1 }, { data: aptitudeRows, error: e2 }, { data: interviewRows, error: e3 }] = await Promise.all([\n      sb.from('user_score_averages').select('resume_score, ats_score, interview_score, communication_score, coding_score, aptitude_score'),\n      sb.from('aptitude_attempts').select('weak_areas'),\n      sb.from('interviews').select('weaknesses').eq('status', 'completed'),\n    ]);\n    if (e1) throw e1;\n    if (e2) throw e2;\n    if (e3) throw e3;\n\n    const rows = scoreRows || [];\n    const averageByCategory = {\n      resume: average(rows.map((r) => r.resume_score)),\n      ats: average(rows.map((r) => r.ats_score)),\n      interview: average(rows.map((r) => r.interview_score)),\n      communication: average(rows.map((r) => r.communication_score)),\n      coding: average(rows.map((r) => r.coding_score)),\n      aptitude: average(rows.map((r) => r.aptitude_score)),\n    };\n    const weakestCategory = Object.entries(averageByCategory).sort((a, b) => a[1] - b[1])[0]?.[0] || null;\n\n    const topAptitudeWeakAreas = tallyTopN((aptitudeRows || []).map((r) => r.weak_areas));\n    const topInterviewWeaknesses = tallyTopN((interviewRows || []).map((r) => r.weaknesses));\n\n    res.json({\n      success: true,\n      analytics: {\n        averageByCategory,\n        weakestCategory,\n        topAptitudeWeakAreas,\n        topInterviewWeaknesses,\n        studentsCounted: rows.length,\n      },\n    });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { getAnalytics };\n",
  "backend/controllers/adminAuditLogController.js": "import { adminAuditLogRepository } from '../repositories/adminAuditLog.repository.js';\n\nexport const getAuditLog = async (req, res, next) => {\n  try {\n    const limit = Math.min(Number(req.query.limit) || 100, 500);\n    const entries = await adminAuditLogRepository.list(limit);\n    res.json({ success: true, entries });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { getAuditLog };\n",
  "backend/controllers/adminAuthController.js": "import * as adminAuthService from '../services/adminAuth.service.js';\n\nexport const loginAdmin = async (req, res, next) => {\n  try {\n    const { token, admin } = await adminAuthService.loginAdmin(req.body);\n    res.json({ success: true, token, admin });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const getAdminProfile = async (req, res) => {\n  const { password_hash, ...safeAdmin } = req.admin;\n  res.json({ success: true, admin: safeAdmin });\n};\n\nexport default { loginAdmin, getAdminProfile };\n",
  "backend/controllers/adminDashboardController.js": "import { getDashboardStats } from '../services/adminDashboard.service.js';\n\nexport const getDashboard = async (req, res, next) => {\n  try {\n    const stats = await getDashboardStats();\n    res.json({ success: true, stats });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { getDashboard };\n",
  "backend/controllers/adminEvaluationsController.js": "import { getSupabase } from '../config/supabase.js';\n\n// Lets staff review AI-scored interview answers. Kept as a direct,\n// read-only query (no write path) since this is a review/inspection tool,\n// not a place that changes student data.\nexport const listEvaluations = async (req, res, next) => {\n  try {\n    const sb = getSupabase();\n    const limit = Math.min(Number(req.query.limit) || 50, 200);\n    const { data, error } = await sb\n      .from('interview_answers')\n      .select('id, interview_id, question_text, user_answer, score, clarity_score, grammar_score, confidence_score, technical_score, feedback, evaluated_at, interviews(role, type, user_id, users(name, email))')\n      .order('evaluated_at', { ascending: false })\n      .limit(limit);\n    if (error) throw error;\n\n    const evaluations = (data || []).map((row) => {\n      const interview = Array.isArray(row.interviews) ? row.interviews[0] : row.interviews;\n      const student = interview ? (Array.isArray(interview.users) ? interview.users[0] : interview.users) : null;\n      return {\n        id: row.id,\n        questionText: row.question_text,\n        userAnswer: row.user_answer,\n        score: row.score,\n        clarityScore: row.clarity_score,\n        grammarScore: row.grammar_score,\n        confidenceScore: row.confidence_score,\n        technicalScore: row.technical_score,\n        feedback: row.feedback,\n        evaluatedAt: row.evaluated_at,\n        interviewType: interview?.type,\n        role: interview?.role,\n        studentName: student?.name,\n        studentEmail: student?.email,\n      };\n    });\n\n    res.json({ success: true, evaluations });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { listEvaluations };\n",
  "backend/controllers/adminNotificationsController.js": "import { adminNotificationsRepository } from '../repositories/adminNotifications.repository.js';\n\nexport const listNotifications = async (req, res, next) => {\n  try {\n    const [notifications, unreadCount] = await Promise.all([\n      adminNotificationsRepository.list(),\n      adminNotificationsRepository.unreadCount(),\n    ]);\n    res.json({ success: true, notifications, unreadCount });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const markNotificationRead = async (req, res, next) => {\n  try {\n    await adminNotificationsRepository.markRead(req.params.id);\n    res.json({ success: true });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const markAllNotificationsRead = async (req, res, next) => {\n  try {\n    await adminNotificationsRepository.markAllRead();\n    res.json({ success: true });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { listNotifications, markNotificationRead, markAllNotificationsRead };\n",
  "backend/controllers/adminQuestionsController.js": "import * as adminQuestionsService from '../services/adminQuestions.service.js';\n\nexport const listQuestions = async (req, res, next) => {\n  try {\n    const { type, difficulty, category, isActive } = req.query;\n    const filters = { type, difficulty, category };\n    if (isActive !== undefined) filters.isActive = isActive === 'true';\n    const questions = await adminQuestionsService.listQuestions(filters);\n    res.json({ success: true, questions });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const createQuestion = async (req, res, next) => {\n  try {\n    const question = await adminQuestionsService.createQuestion(req.body, req.admin);\n    res.status(201).json({ success: true, question });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const updateQuestion = async (req, res, next) => {\n  try {\n    const question = await adminQuestionsService.updateQuestion(req.params.id, req.body, req.admin);\n    res.json({ success: true, question });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const activateQuestion = async (req, res, next) => {\n  try {\n    await adminQuestionsService.setQuestionActive(req.params.id, true, req.admin);\n    res.json({ success: true, message: 'Question activated' });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const deactivateQuestion = async (req, res, next) => {\n  try {\n    await adminQuestionsService.setQuestionActive(req.params.id, false, req.admin);\n    res.json({ success: true, message: 'Question deactivated' });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { listQuestions, createQuestion, updateQuestion, activateQuestion, deactivateQuestion };\n",
  "backend/controllers/adminSettingsController.js": "import * as adminSettingsService from '../services/adminSettings.service.js';\nimport { adminAuditLogRepository } from '../repositories/adminAuditLog.repository.js';\n\nexport const getEvaluationSettings = async (req, res, next) => {\n  try {\n    const settings = await adminSettingsService.getEvaluationSettings();\n    res.json({ success: true, settings });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const updateEvaluationSettings = async (req, res, next) => {\n  try {\n    const settings = await adminSettingsService.updateEvaluationSettings(req.body, req.admin);\n    adminAuditLogRepository.log({\n      adminId: req.admin.id, adminName: req.admin.name,\n      action: 'update_evaluation_settings', target: 'evaluation', details: settings,\n    }).catch(() => {});\n    res.json({ success: true, settings });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const getInterviewSettings = async (req, res, next) => {\n  try {\n    const settings = await adminSettingsService.getInterviewSettings();\n    res.json({ success: true, settings });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const updateInterviewSettings = async (req, res, next) => {\n  try {\n    const settings = await adminSettingsService.updateInterviewSettings(req.body, req.admin);\n    adminAuditLogRepository.log({\n      adminId: req.admin.id, adminName: req.admin.name,\n      action: 'update_interview_settings', target: 'interview', details: settings,\n    }).catch(() => {});\n    res.json({ success: true, settings });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { getEvaluationSettings, updateEvaluationSettings, getInterviewSettings, updateInterviewSettings };\n",
  "backend/controllers/adminStaffController.js": "import { adminUserRepository } from '../repositories/adminUser.repository.js';\nimport { createAdmin } from '../services/adminAuth.service.js';\nimport { adminAuditLogRepository } from '../repositories/adminAuditLog.repository.js';\nimport { adminNotificationsRepository } from '../repositories/adminNotifications.repository.js';\n\nexport const listStaff = async (req, res, next) => {\n  try {\n    const staff = await adminUserRepository.list();\n    res.json({ success: true, staff });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const createStaff = async (req, res, next) => {\n  try {\n    const created = await createAdmin(req.body);\n    const { password_hash, ...safe } = created;\n    adminAuditLogRepository.log({\n      adminId: req.admin.id, adminName: req.admin.name, action: 'add_staff', target: created.id,\n      details: { email: created.email, role: created.role },\n    }).catch(() => {});\n    adminNotificationsRepository.create({\n      title: 'Staff account created',\n      message: `${req.admin.name} created a ${created.role} account for ${created.name}`,\n      type: 'info',\n    }).catch(() => {});\n    res.status(201).json({ success: true, staff: safe });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const deactivateStaff = async (req, res, next) => {\n  try {\n    if (req.params.id === req.admin.id) {\n      return res.status(400).json({ success: false, message: \"You can't deactivate your own account\" });\n    }\n    await adminUserRepository.setActive(req.params.id, false);\n    adminAuditLogRepository.log({\n      adminId: req.admin.id, adminName: req.admin.name, action: 'deactivate_staff', target: req.params.id,\n    }).catch(() => {});\n    adminNotificationsRepository.create({\n      title: 'Staff account deactivated',\n      message: `${req.admin.name} deactivated a staff account`,\n      type: 'warning',\n    }).catch(() => {});\n    res.json({ success: true, message: 'Staff account deactivated' });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const reactivateStaff = async (req, res, next) => {\n  try {\n    await adminUserRepository.setActive(req.params.id, true);\n    adminAuditLogRepository.log({\n      adminId: req.admin.id, adminName: req.admin.name, action: 'reactivate_staff', target: req.params.id,\n    }).catch(() => {});\n    res.json({ success: true, message: 'Staff account reactivated' });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { listStaff, createStaff, deactivateStaff, reactivateStaff };\n",
  "backend/controllers/adminStudentsController.js": "import * as adminStudentsService from '../services/adminStudents.service.js';\n\nexport const listStudents = async (req, res, next) => {\n  try {\n    const students = await adminStudentsService.listStudents({ search: req.query.search || '' });\n    res.json({ success: true, students });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const getStudentDetail = async (req, res, next) => {\n  try {\n    const student = await adminStudentsService.getStudentDetail(req.params.id);\n    res.json({ success: true, student });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const deactivateStudent = async (req, res, next) => {\n  try {\n    await adminStudentsService.setStudentActive(req.params.id, false, req.admin);\n    res.json({ success: true, message: 'Student account deactivated' });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const reactivateStudent = async (req, res, next) => {\n  try {\n    await adminStudentsService.setStudentActive(req.params.id, true, req.admin);\n    res.json({ success: true, message: 'Student account reactivated' });\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport const exportStudentsCsv = async (req, res, next) => {\n  try {\n    const csv = await adminStudentsService.exportStudentsCsv();\n    res.setHeader('Content-Type', 'text/csv');\n    res.setHeader('Content-Disposition', 'attachment; filename=\"students.csv\"');\n    res.send(csv);\n  } catch (err) {\n    next(err);\n  }\n};\n\nexport default { listStudents, getStudentDetail, deactivateStudent, reactivateStudent, exportStudentsCsv };\n",
  "backend/middleware/adminAuth.middleware.js": "import { verifyAdminToken } from '../services/adminAuth.service.js';\nimport { adminUserRepository } from '../repositories/adminUser.repository.js';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// protectAdmin — verifies an admin-scoped JWT on every admin route.\n// Mirrors backend/middleware/auth.middleware.js but checks the separate\n// admin_users table and the 'admin' token scope, so it never accepts a\n// student token and a student route never accepts an admin token.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport async function protectAdmin(req, res, next) {\n  const authHeader = req.headers.authorization;\n  if (!authHeader || !authHeader.startsWith('Bearer ')) {\n    return res.status(401).json({ success: false, message: 'Not authorized — no token provided', errorCode: 'NO_TOKEN' });\n  }\n\n  const token = authHeader.split(' ')[1];\n\n  let decoded;\n  try {\n    decoded = verifyAdminToken(token);\n  } catch (err) {\n    const message = err.name === 'TokenExpiredError'\n      ? 'Session expired — please login again'\n      : 'Not authorized — invalid token';\n    return res.status(401).json({ success: false, message, errorCode: 'INVALID_TOKEN' });\n  }\n\n  try {\n    const admin = await adminUserRepository.findById(decoded.id);\n    if (!admin) {\n      return res.status(401).json({ success: false, message: 'Admin account no longer exists', errorCode: 'ADMIN_NOT_FOUND' });\n    }\n    if (admin.is_active === false) {\n      return res.status(403).json({ success: false, message: 'This admin account has been deactivated', errorCode: 'ADMIN_DEACTIVATED' });\n    }\n    req.admin = admin;\n    return next();\n  } catch (err) {\n    console.error('Admin auth middleware DB error:', err.message);\n    return res.status(503).json({ success: false, message: 'Authentication service temporarily unavailable', errorCode: 'DB_UNAVAILABLE' });\n  }\n}\n\n// Restricts a route to the 'admin' role only (not 'staff'). Use after protectAdmin.\nexport function requireAdminRole(req, res, next) {\n  if (req.admin?.role !== 'admin') {\n    return res.status(403).json({ success: false, message: 'This action requires an admin role, not staff', errorCode: 'INSUFFICIENT_ROLE' });\n  }\n  next();\n}\n\nexport default { protectAdmin, requireAdminRole };\n",
  "backend/repositories/adminAuditLog.repository.js": "import { getSupabase } from '../config/supabase.js';\n\nexport const adminAuditLogRepository = {\n  async log({ adminId, adminName, action, target, details = {} }) {\n    const sb = getSupabase();\n    // Audit logging must never block or break the action it's recording.\n    const { error } = await sb.from('admin_audit_log').insert({\n      admin_id: adminId, admin_name: adminName, action, target, details,\n    });\n    if (error) console.error('Audit log write failed:', error.message);\n  },\n\n  async list(limit = 100) {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_audit_log')\n      .select('*')\n      .order('created_at', { ascending: false })\n      .limit(limit);\n    if (error) throw error;\n    return data || [];\n  },\n};\n\nexport default adminAuditLogRepository;\n",
  "backend/repositories/adminNotifications.repository.js": "import { getSupabase } from '../config/supabase.js';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Admin Notifications Repository — a simple staff-wide feed (no per-admin\n// read tracking: with a small staff team, \"read by anyone\" marking it read\n// for everyone is a reasonable trade-off). Notification creation must never\n// block or break the action that triggered it, so `create` swallows its own\n// errors — callers fire-and-forget it the same way they do audit logging.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport const adminNotificationsRepository = {\n  async create({ title, message, type = 'info' }) {\n    const sb = getSupabase();\n    const { error } = await sb.from('admin_notifications').insert({ title, message, type });\n    if (error) console.error('Notification create failed:', error.message);\n  },\n\n  async list(limit = 30) {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_notifications')\n      .select('*')\n      .order('created_at', { ascending: false })\n      .limit(limit);\n    if (error) throw error;\n    return data || [];\n  },\n\n  async markRead(id) {\n    const sb = getSupabase();\n    const { error } = await sb.from('admin_notifications').update({ is_read: true }).eq('id', id);\n    if (error) throw error;\n  },\n\n  async markAllRead() {\n    const sb = getSupabase();\n    const { error } = await sb.from('admin_notifications').update({ is_read: true }).eq('is_read', false);\n    if (error) throw error;\n  },\n\n  async unreadCount() {\n    const sb = getSupabase();\n    const { count, error } = await sb\n      .from('admin_notifications')\n      .select('id', { count: 'exact', head: true })\n      .eq('is_read', false);\n    if (error) throw error;\n    return count || 0;\n  },\n};\n\nexport default adminNotificationsRepository;\n",
  "backend/repositories/adminQuestions.repository.js": "import { getSupabase } from '../config/supabase.js';\n\nexport const adminQuestionsRepository = {\n\n  async list({ type, difficulty, category, isActive } = {}) {\n    const sb = getSupabase();\n    let query = sb.from('questions').select('*').order('created_at', { ascending: false });\n    if (type) query = query.eq('type', type);\n    if (difficulty) query = query.eq('difficulty', difficulty);\n    if (category) query = query.eq('category', category);\n    if (isActive !== undefined) query = query.eq('is_active', isActive);\n    const { data, error } = await query;\n    if (error) throw error;\n    return data || [];\n  },\n\n  async findById(id) {\n    const sb = getSupabase();\n    const { data, error } = await sb.from('questions').select('*').eq('id', id).single();\n    if (error && error.code !== 'PGRST116') throw error;\n    return data || null;\n  },\n\n  async create(q, adminId) {\n    const sb = getSupabase();\n    const { data, error } = await sb.from('questions').insert({\n      type: q.type,\n      category: q.category || '',\n      difficulty: q.difficulty || 'Medium',\n      title: q.title || (q.questionText || '').slice(0, 80),\n      question_text: q.questionText,\n      payload: q.payload || {},\n      is_active: true,\n      source: 'admin',\n      created_by: adminId,\n    }).select().single();\n    if (error) throw error;\n    return data;\n  },\n\n  async update(id, fields) {\n    const sb = getSupabase();\n    const updatePayload = { updated_at: new Date().toISOString() };\n    if (fields.category !== undefined) updatePayload.category = fields.category;\n    if (fields.difficulty !== undefined) updatePayload.difficulty = fields.difficulty;\n    if (fields.title !== undefined) updatePayload.title = fields.title;\n    if (fields.questionText !== undefined) updatePayload.question_text = fields.questionText;\n    if (fields.payload !== undefined) updatePayload.payload = fields.payload;\n    const { data, error } = await sb.from('questions').update(updatePayload).eq('id', id).select().single();\n    if (error) throw error;\n    return data;\n  },\n\n  async setActive(id, isActive) {\n    const sb = getSupabase();\n    const { error } = await sb.from('questions').update({ is_active: isActive, updated_at: new Date().toISOString() }).eq('id', id);\n    if (error) throw error;\n  },\n};\n\nexport default adminQuestionsRepository;\n",
  "backend/repositories/adminSettings.repository.js": "import { getSupabase } from '../config/supabase.js';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Admin Settings Repository — key/value config rows in `admin_settings`.\n// Falls back to sane defaults only if a row hasn't been created yet (the\n// admin_module migration inserts both rows, so this is just a safety net).\n// ─────────────────────────────────────────────────────────────────────────────\n\nconst DEFAULTS = {\n  evaluation: { passingScore: 60, attentionThreshold: 50 },\n  interview: { defaultDurationMinutes: 15, questionsPerInterview: 5 },\n};\n\nexport const adminSettingsRepository = {\n  async get(key) {\n    const sb = getSupabase();\n    const { data, error } = await sb.from('admin_settings').select('*').eq('key', key).single();\n    if (error && error.code !== 'PGRST116') throw error;\n    return data ? data.value : (DEFAULTS[key] || {});\n  },\n\n  async set(key, value, updatedBy) {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_settings')\n      .upsert({ key, value, updated_by: updatedBy, updated_at: new Date().toISOString() }, { onConflict: 'key' })\n      .select()\n      .single();\n    if (error) throw error;\n    return data.value;\n  },\n};\n\nexport default adminSettingsRepository;\n",
  "backend/repositories/adminStats.repository.js": "import { getSupabase } from '../config/supabase.js';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Admin Stats Repository — read-only aggregate queries for the Admin\n// Dashboard. Aggregation is done in JS after a scoped fetch (fine at\n// student-project scale); if this ever needs to run at real scale, these\n// should become Postgres RPC functions instead.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport const adminStatsRepository = {\n\n  async getStudentCounts() {\n    const sb = getSupabase();\n    const { count: total, error: e1 } = await sb.from('users').select('*', { count: 'exact', head: true });\n    if (e1) throw e1;\n    const { count: active, error: e2 } = await sb.from('users').select('*', { count: 'exact', head: true }).neq('is_active', false);\n    if (e2) throw e2;\n    return { total: total || 0, active: active || 0 };\n  },\n\n  async getActiveQuestionCount() {\n    const sb = getSupabase();\n    const { count, error } = await sb.from('questions').select('*', { count: 'exact', head: true }).eq('is_active', true);\n    if (error) throw error;\n    return count || 0;\n  },\n\n  async getCompletedInterviews() {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('interviews')\n      .select('id, total_score, completed_at')\n      .eq('status', 'completed')\n      .order('completed_at', { ascending: false })\n      .limit(2000); // generous cap for a student-project dataset\n    if (error) throw error;\n    return data || [];\n  },\n\n  async getStudentsWithScores() {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('users')\n      .select('id, name, email, college, last_login_at, is_active, user_score_averages(overall_score)');\n    if (error) throw error;\n    return (data || []).map((u) => {\n      // Supabase can return an embedded to-one relation as an object or a\n      // single-element array depending on how the FK constraint is read —\n      // handle both so this never silently breaks.\n      const avgRow = Array.isArray(u.user_score_averages) ? u.user_score_averages[0] : u.user_score_averages;\n      return {\n        id: u.id,\n        name: u.name,\n        email: u.email,\n        college: u.college,\n        lastActiveAt: u.last_login_at,\n        isActive: u.is_active !== false,\n        overallScore: avgRow?.overall_score ?? null,\n      };\n    });\n  },\n};\n\nexport default adminStatsRepository;\n",
  "backend/repositories/adminStudents.repository.js": "import { getSupabase } from '../config/supabase.js';\n\nexport const adminStudentsRepository = {\n\n  async listStudents() {\n    const sb = getSupabase();\n    const [{ data: users, error: e1 }, { data: interviews, error: e2 }] = await Promise.all([\n      sb.from('users').select('id, name, email, college, last_login_at, is_active, created_at, user_score_averages(overall_score)'),\n      sb.from('interviews').select('id, user_id'),\n    ]);\n    if (e1) throw e1;\n    if (e2) throw e2;\n\n    const interviewCounts = new Map();\n    for (const iv of interviews || []) {\n      interviewCounts.set(iv.user_id, (interviewCounts.get(iv.user_id) || 0) + 1);\n    }\n\n    return (users || []).map((u) => {\n      const avgRow = Array.isArray(u.user_score_averages) ? u.user_score_averages[0] : u.user_score_averages;\n      return {\n        id: u.id,\n        name: u.name,\n        email: u.email,\n        college: u.college,\n        interviews: interviewCounts.get(u.id) || 0,\n        averageScore: avgRow?.overall_score ?? null,\n        lastActiveAt: u.last_login_at,\n        isActive: u.is_active !== false,\n        joinedAt: u.created_at,\n      };\n    });\n  },\n\n  async getStudentDetail(userId) {\n    const sb = getSupabase();\n    const [\n      { data: user, error: e1 },\n      { data: scores },\n      { data: interviews },\n      { data: aptitude },\n      { data: coding },\n      { data: communication },\n    ] = await Promise.all([\n      sb.from('users').select('*').eq('id', userId).single(),\n      sb.from('user_score_averages').select('*').eq('user_id', userId).single(),\n      sb.from('interviews').select('id, type, role, total_score, status, completed_at').eq('user_id', userId).order('created_at', { ascending: false }).limit(20),\n      sb.from('aptitude_attempts').select('id, category, score, accuracy, submitted_at').eq('user_id', userId).order('created_at', { ascending: false }).limit(20),\n      sb.from('coding_attempts').select('id, problem_title, difficulty, score, status, created_at').eq('user_id', userId).order('created_at', { ascending: false }).limit(20),\n      sb.from('communication_attempts').select('id, overall_score, created_at').eq('user_id', userId).order('created_at', { ascending: false }).limit(20),\n    ]);\n    if (e1) throw e1;\n    if (!user) return null;\n\n    const { password_hash, ...safeUser } = user;\n    return {\n      ...safeUser,\n      scores: scores || null,\n      recentInterviews: interviews || [],\n      recentAptitude: aptitude || [],\n      recentCoding: coding || [],\n      recentCommunication: communication || [],\n    };\n  },\n\n  async setActive(userId, isActive) {\n    const sb = getSupabase();\n    const { error } = await sb.from('users').update({ is_active: isActive }).eq('id', userId);\n    if (error) throw error;\n  },\n};\n\nexport default adminStudentsRepository;\n",
  "backend/repositories/adminUser.repository.js": "import { getSupabase } from '../config/supabase.js';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Admin User Repository — all database operations for admin_users.\n// Completely separate table from students (`users`) — by design, so a bug\n// or compromise on one side can never grant access to the other.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport const adminUserRepository = {\n\n  async findByEmail(email) {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_users')\n      .select('*')\n      .eq('email', email.toLowerCase().trim())\n      .single();\n    if (error && error.code !== 'PGRST116') throw error;\n    return data || null;\n  },\n\n  async findById(id) {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_users')\n      .select('*')\n      .eq('id', id)\n      .single();\n    if (error && error.code !== 'PGRST116') throw error;\n    return data || null;\n  },\n\n  async create({ email, passwordHash, name, role = 'staff' }) {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_users')\n      .insert({\n        email: email.toLowerCase().trim(),\n        password_hash: passwordHash,\n        name: name.trim(),\n        role,\n      })\n      .select()\n      .single();\n    if (error) throw error;\n    return data;\n  },\n\n  async list() {\n    const sb = getSupabase();\n    const { data, error } = await sb\n      .from('admin_users')\n      .select('id, email, name, role, is_active, created_at, last_login_at')\n      .order('created_at', { ascending: true });\n    if (error) throw error;\n    return data || [];\n  },\n\n  async setActive(id, isActive) {\n    const sb = getSupabase();\n    const { error } = await sb.from('admin_users').update({ is_active: isActive }).eq('id', id);\n    if (error) throw error;\n  },\n\n  async recordLogin(id) {\n    const sb = getSupabase();\n    await sb.from('admin_users').update({ last_login_at: new Date().toISOString() }).eq('id', id);\n  },\n};\n\nexport default adminUserRepository;\n",
  "backend/routes/adminAuthRoutes.js": "import express from 'express';\nimport { loginAdmin, getAdminProfile } from '../controllers/adminAuthController.js';\nimport { protectAdmin } from '../middleware/adminAuth.middleware.js';\n\nconst router = express.Router();\n\nrouter.post('/login', loginAdmin);\nrouter.get('/profile', protectAdmin, getAdminProfile);\n\nexport default router;\n",
  "backend/routes/adminRoutes.js": "import express from 'express';\nimport { protectAdmin, requireAdminRole } from '../middleware/adminAuth.middleware.js';\n\nimport { getDashboard } from '../controllers/adminDashboardController.js';\nimport {\n  listStudents, getStudentDetail, deactivateStudent, reactivateStudent, exportStudentsCsv,\n} from '../controllers/adminStudentsController.js';\nimport {\n  listQuestions, createQuestion, updateQuestion, activateQuestion, deactivateQuestion,\n} from '../controllers/adminQuestionsController.js';\nimport { listStaff, createStaff, deactivateStaff, reactivateStaff } from '../controllers/adminStaffController.js';\nimport { listEvaluations } from '../controllers/adminEvaluationsController.js';\nimport { getAnalytics } from '../controllers/adminAnalyticsController.js';\nimport {\n  getEvaluationSettings, updateEvaluationSettings, getInterviewSettings, updateInterviewSettings,\n} from '../controllers/adminSettingsController.js';\nimport {\n  listNotifications, markNotificationRead, markAllNotificationsRead,\n} from '../controllers/adminNotificationsController.js';\nimport { getAlerts } from '../controllers/adminAlertsController.js';\nimport { getAuditLog } from '../controllers/adminAuditLogController.js';\n\nconst router = express.Router();\n\n// Every route below requires a valid admin/staff token.\nrouter.use(protectAdmin);\n\n// Dashboard\nrouter.get('/dashboard', getDashboard);\n\n// Students\nrouter.get('/students', listStudents);\nrouter.get('/students/export', exportStudentsCsv);\nrouter.get('/students/:id', getStudentDetail);\nrouter.put('/students/:id/deactivate', deactivateStudent);\nrouter.put('/students/:id/reactivate', reactivateStudent);\n\n// Question Bank\nrouter.get('/questions', listQuestions);\nrouter.post('/questions', createQuestion);\nrouter.put('/questions/:id', updateQuestion);\nrouter.put('/questions/:id/activate', activateQuestion);\nrouter.put('/questions/:id/deactivate', deactivateQuestion);\n\n// Staff management — creating/removing staff is admin-role only\nrouter.get('/staff', listStaff);\nrouter.post('/staff', requireAdminRole, createStaff);\nrouter.put('/staff/:id/deactivate', requireAdminRole, deactivateStaff);\nrouter.put('/staff/:id/reactivate', requireAdminRole, reactivateStaff);\n\n// Evaluations review\nrouter.get('/evaluations', listEvaluations);\n\n// Analytics & skill gaps\nrouter.get('/analytics', getAnalytics);\n\n// Settings — any staff can view, only admins can change\nrouter.get('/settings/evaluation', getEvaluationSettings);\nrouter.put('/settings/evaluation', requireAdminRole, updateEvaluationSettings);\nrouter.get('/settings/interview', getInterviewSettings);\nrouter.put('/settings/interview', requireAdminRole, updateInterviewSettings);\n\n// Notifications — shared staff-wide feed\nrouter.get('/notifications', listNotifications);\nrouter.put('/notifications/read-all', markAllNotificationsRead);\nrouter.put('/notifications/:id/read', markNotificationRead);\n\n// Alerts — computed live from real student data\nrouter.get('/alerts', getAlerts);\n\n// Audit log — admin-role only\nrouter.get('/audit-log', requireAdminRole, getAuditLog);\n\nexport default router;\n",
  "backend/services/adminAlerts.service.js": "import { adminStatsRepository } from '../repositories/adminStats.repository.js';\nimport { adminSettingsRepository } from '../repositories/adminSettings.repository.js';\n\nconst INACTIVITY_DAYS = 14;\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Admin Alerts — computed fresh from real data every call, nothing cached or\n// hardcoded. Two kinds: low overall score (threshold comes from the\n// Evaluation settings an admin can actually change) and no login activity\n// in INACTIVITY_DAYS. Deactivated students are excluded — nothing to alert\n// staff about for an account that's already locked out.\n// ─────────────────────────────────────────────────────────────────────────────\n\nexport async function getAlerts() {\n  const [students, evaluationSettings] = await Promise.all([\n    adminStatsRepository.getStudentsWithScores(),\n    adminSettingsRepository.get('evaluation'),\n  ]);\n  const threshold = Number(evaluationSettings?.attentionThreshold);\n  const effectiveThreshold = Number.isFinite(threshold) ? threshold : 50;\n\n  const now = Date.now();\n  const inactivityCutoff = now - INACTIVITY_DAYS * 24 * 60 * 60 * 1000;\n\n  const alerts = [];\n  for (const s of students) {\n    if (!s.isActive) continue;\n\n    if (s.overallScore !== null && s.overallScore < effectiveThreshold) {\n      alerts.push({\n        type: 'low_score',\n        severity: 'high',\n        studentId: s.id,\n        name: s.name,\n        email: s.email,\n        college: s.college,\n        detail: `Overall score ${s.overallScore}/100 is below the ${effectiveThreshold} threshold`,\n      });\n    }\n\n    const lastActiveMs = s.lastActiveAt ? new Date(s.lastActiveAt).getTime() : null;\n    if (lastActiveMs && lastActiveMs < inactivityCutoff) {\n      const days = Math.floor((now - lastActiveMs) / (24 * 60 * 60 * 1000));\n      alerts.push({\n        type: 'inactive',\n        severity: 'medium',\n        studentId: s.id,\n        name: s.name,\n        email: s.email,\n        college: s.college,\n        detail: `No login activity in ${days} days`,\n      });\n    }\n  }\n\n  const severityRank = { high: 0, medium: 1, low: 2 };\n  alerts.sort((a, b) => severityRank[a.severity] - severityRank[b.severity]);\n  return alerts;\n}\n\nexport default { getAlerts };\n",
  "backend/services/adminAuth.service.js": "import bcrypt from 'bcryptjs';\nimport jwt from 'jsonwebtoken';\nimport { adminUserRepository } from '../repositories/adminUser.repository.js';\n\n// ─────────────────────────────────────────────────────────────────────────────\n// Admin Auth Service — separate token scope from student auth, so a student\n// JWT can never be replayed against an admin-only route and vice versa.\n// There is no public \"admin register\" endpoint on purpose: admin accounts\n// are created with backend/scripts/create-admin.mjs, run by someone with\n// server access only.\n// ─────────────────────────────────────────────────────────────────────────────\n\nfunction getJwtSecret() {\n  const secret = process.env.JWT_SECRET;\n  if (!secret) throw new Error('JWT_SECRET environment variable is required but not set.');\n  return secret;\n}\n\nexport function generateAdminToken(adminId, role) {\n  return jwt.sign(\n    { id: adminId, role, scope: 'admin' },\n    getJwtSecret(),\n    { expiresIn: process.env.ADMIN_JWT_EXPIRE || '12h' }\n  );\n}\n\nexport function verifyAdminToken(token) {\n  const decoded = jwt.verify(token, getJwtSecret());\n  if (decoded.scope !== 'admin') {\n    throw Object.assign(new Error('Not an admin token'), { statusCode: 401 });\n  }\n  return decoded;\n}\n\nexport async function loginAdmin({ email, password }) {\n  if (!email || !password) {\n    throw Object.assign(new Error('Please provide email and password'), { statusCode: 400 });\n  }\n  const admin = await adminUserRepository.findByEmail(email);\n  if (!admin) {\n    throw Object.assign(new Error('Invalid email or password'), { statusCode: 401 });\n  }\n  if (admin.is_active === false) {\n    throw Object.assign(new Error('This admin account has been deactivated'), { statusCode: 403 });\n  }\n  const isMatch = await bcrypt.compare(password, admin.password_hash);\n  if (!isMatch) {\n    throw Object.assign(new Error('Invalid email or password'), { statusCode: 401 });\n  }\n  adminUserRepository.recordLogin(admin.id).catch(() => {}); // fire-and-forget\n  const token = generateAdminToken(admin.id, admin.role);\n  const { password_hash, ...safeAdmin } = admin;\n  return { token, admin: safeAdmin };\n}\n\nexport async function createAdmin({ email, password, name, role = 'staff' }) {\n  if (!email || !password || !name) {\n    throw Object.assign(new Error('Please provide name, email and password'), { statusCode: 400 });\n  }\n  if (password.length < 6) {\n    throw Object.assign(new Error('Password must be at least 6 characters'), { statusCode: 400 });\n  }\n  const existing = await adminUserRepository.findByEmail(email);\n  if (existing) {\n    throw Object.assign(new Error('An admin account with this email already exists'), { statusCode: 400 });\n  }\n  const passwordHash = await bcrypt.hash(password, 10);\n  return adminUserRepository.create({ email, passwordHash, name, role });\n}\n\nexport default { generateAdminToken, verifyAdminToken, loginAdmin, createAdmin };\n",
  "backend/services/adminDashboard.service.js": "import { adminStatsRepository } from '../repositories/adminStats.repository.js';\nimport { adminSettingsRepository } from '../repositories/adminSettings.repository.js';\n\nconst FALLBACK_ATTENTION_THRESHOLD = 50; // used only if the settings row can't be read\n\nfunction dayLabel(date) {\n  return date.toISOString().slice(0, 10); // YYYY-MM-DD\n}\n\nfunction startOfWeek(date) {\n  const d = new Date(date);\n  const day = d.getUTCDay(); // 0 = Sunday\n  d.setUTCDate(d.getUTCDate() - day);\n  d.setUTCHours(0, 0, 0, 0);\n  return d;\n}\n\nexport async function getDashboardStats() {\n  const [studentCounts, activeQuestions, completedInterviews, students, evaluationSettings] = await Promise.all([\n    adminStatsRepository.getStudentCounts(),\n    adminStatsRepository.getActiveQuestionCount(),\n    adminStatsRepository.getCompletedInterviews(),\n    adminStatsRepository.getStudentsWithScores(),\n    adminSettingsRepository.get('evaluation'),\n  ]);\n  // Reads the live Evaluation setting an admin can change — not a hardcoded\n  // constant, so editing it on the Settings page actually changes who shows\n  // up here, not just what the Settings page displays.\n  const attentionThresholdNum = Number(evaluationSettings?.attentionThreshold);\n  const ATTENTION_THRESHOLD = Number.isFinite(attentionThresholdNum) ? attentionThresholdNum : FALLBACK_ATTENTION_THRESHOLD;\n\n  const interviewsCompleted = completedInterviews.length;\n  const avgInterviewScore = interviewsCompleted > 0\n    ? Math.round((completedInterviews.reduce((sum, i) => sum + (Number(i.total_score) || 0), 0) / interviewsCompleted) * 10) / 10\n    : 0;\n\n  // ── 30-day average score trend (by day) ──────────────────────────────────\n  const now = new Date();\n  const since30 = new Date(now);\n  since30.setUTCDate(since30.getUTCDate() - 29);\n  since30.setUTCHours(0, 0, 0, 0);\n\n  const byDay = new Map(); // dayLabel -> { sum, count }\n  for (const iv of completedInterviews) {\n    if (!iv.completed_at) continue;\n    const d = new Date(iv.completed_at);\n    if (d < since30) continue;\n    const key = dayLabel(d);\n    const bucket = byDay.get(key) || { sum: 0, count: 0 };\n    bucket.sum += Number(iv.total_score) || 0;\n    bucket.count += 1;\n    byDay.set(key, bucket);\n  }\n  const performanceTrend = [];\n  for (let i = 0; i < 30; i++) {\n    const d = new Date(since30);\n    d.setUTCDate(d.getUTCDate() + i);\n    const key = dayLabel(d);\n    const bucket = byDay.get(key);\n    performanceTrend.push({\n      date: key,\n      averageScore: bucket ? Math.round((bucket.sum / bucket.count) * 10) / 10 : null,\n    });\n  }\n\n  // ── Interviews completed per week (last 8 weeks) ─────────────────────────\n  const since8Weeks = new Date(now);\n  since8Weeks.setUTCDate(since8Weeks.getUTCDate() - 7 * 8);\n  const byWeek = new Map();\n  for (const iv of completedInterviews) {\n    if (!iv.completed_at) continue;\n    const d = new Date(iv.completed_at);\n    if (d < since8Weeks) continue;\n    const weekStart = startOfWeek(d);\n    const key = dayLabel(weekStart);\n    byWeek.set(key, (byWeek.get(key) || 0) + 1);\n  }\n  const weeklyInterviews = [];\n  for (let i = 7; i >= 0; i--) {\n    const d = startOfWeek(now);\n    d.setUTCDate(d.getUTCDate() - 7 * i);\n    const key = dayLabel(d);\n    weeklyInterviews.push({ weekStarting: key, interviews: byWeek.get(key) || 0 });\n  }\n\n  // ── Students needing attention ────────────────────────────────────────────\n  const studentsNeedingAttention = students\n    .filter((s) => s.isActive && s.overallScore !== null && s.overallScore < ATTENTION_THRESHOLD)\n    .sort((a, b) => a.overallScore - b.overallScore)\n    .slice(0, 20)\n    .map((s) => ({ id: s.id, name: s.name, email: s.email, college: s.college, overallScore: s.overallScore }));\n\n  return {\n    totalStudents: studentCounts.total,\n    activeStudents: studentCounts.active,\n    interviewsCompleted,\n    averageInterviewScore: avgInterviewScore,\n    activeQuestions,\n    performanceTrend,\n    weeklyInterviews,\n    studentsNeedingAttention,\n    attentionThreshold: ATTENTION_THRESHOLD,\n  };\n}\n\nexport default { getDashboardStats };\n",
  "backend/services/adminQuestions.service.js": "import { adminQuestionsRepository } from '../repositories/adminQuestions.repository.js';\nimport { adminAuditLogRepository } from '../repositories/adminAuditLog.repository.js';\nimport { adminNotificationsRepository } from '../repositories/adminNotifications.repository.js';\n\nconst VALID_TYPES = ['aptitude', 'technical', 'coding', 'behavioural'];\n\nfunction validateNewQuestion(q) {\n  if (!q.type || !VALID_TYPES.includes(q.type)) {\n    throw Object.assign(new Error(`type must be one of: ${VALID_TYPES.join(', ')}`), { statusCode: 400 });\n  }\n  if (!q.questionText || !q.questionText.trim()) {\n    throw Object.assign(new Error('questionText is required'), { statusCode: 400 });\n  }\n  if (q.type === 'aptitude') {\n    if (!Array.isArray(q.payload?.options) || q.payload.options.length < 2) {\n      throw Object.assign(new Error('Aptitude questions need at least 2 options in payload.options'), { statusCode: 400 });\n    }\n    if (!q.payload?.correctAnswer) {\n      throw Object.assign(new Error('Aptitude questions need payload.correctAnswer'), { statusCode: 400 });\n    }\n  }\n}\n\nexport async function listQuestions(filters) {\n  return adminQuestionsRepository.list(filters);\n}\n\nexport async function createQuestion(q, admin) {\n  validateNewQuestion(q);\n  const created = await adminQuestionsRepository.create(q, admin.id);\n  adminAuditLogRepository.log({\n    adminId: admin.id, adminName: admin.name, action: 'add_question', target: created.id,\n    details: { type: created.type, title: created.title },\n  }).catch(() => {});\n  adminNotificationsRepository.create({\n    title: 'New question added',\n    message: `${admin.name} added a ${created.type} question${created.category ? ` (${created.category})` : ''}`,\n    type: 'info',\n  }).catch(() => {});\n  return created;\n}\n\nexport async function updateQuestion(id, fields, admin) {\n  const existing = await adminQuestionsRepository.findById(id);\n  if (!existing) throw Object.assign(new Error('Question not found'), { statusCode: 404 });\n  const updated = await adminQuestionsRepository.update(id, fields);\n  adminAuditLogRepository.log({\n    adminId: admin.id, adminName: admin.name, action: 'edit_question', target: id,\n  }).catch(() => {});\n  return updated;\n}\n\nexport async function setQuestionActive(id, isActive, admin) {\n  const existing = await adminQuestionsRepository.findById(id);\n  if (!existing) throw Object.assign(new Error('Question not found'), { statusCode: 404 });\n  await adminQuestionsRepository.setActive(id, isActive);\n  adminAuditLogRepository.log({\n    adminId: admin.id, adminName: admin.name,\n    action: isActive ? 'activate_question' : 'deactivate_question', target: id,\n  }).catch(() => {});\n}\n\nexport default { listQuestions, createQuestion, updateQuestion, setQuestionActive };\n",
  "backend/services/adminSettings.service.js": "import { adminSettingsRepository } from '../repositories/adminSettings.repository.js';\n\nfunction validateEvaluation(v) {\n  const passingScore = Number(v.passingScore);\n  const attentionThreshold = Number(v.attentionThreshold);\n  if (!Number.isFinite(passingScore) || passingScore < 0 || passingScore > 100) {\n    throw Object.assign(new Error('passingScore must be a number between 0 and 100'), { statusCode: 400 });\n  }\n  if (!Number.isFinite(attentionThreshold) || attentionThreshold < 0 || attentionThreshold > 100) {\n    throw Object.assign(new Error('attentionThreshold must be a number between 0 and 100'), { statusCode: 400 });\n  }\n  return { passingScore, attentionThreshold };\n}\n\nfunction validateInterview(v) {\n  const defaultDurationMinutes = Number(v.defaultDurationMinutes);\n  const questionsPerInterview = Number(v.questionsPerInterview);\n  if (!Number.isFinite(defaultDurationMinutes) || defaultDurationMinutes < 1 || defaultDurationMinutes > 180) {\n    throw Object.assign(new Error('defaultDurationMinutes must be a number between 1 and 180'), { statusCode: 400 });\n  }\n  if (!Number.isFinite(questionsPerInterview) || questionsPerInterview < 1 || questionsPerInterview > 50) {\n    throw Object.assign(new Error('questionsPerInterview must be a number between 1 and 50'), { statusCode: 400 });\n  }\n  return { defaultDurationMinutes, questionsPerInterview };\n}\n\nexport async function getEvaluationSettings() {\n  return adminSettingsRepository.get('evaluation');\n}\n\nexport async function updateEvaluationSettings(body, admin) {\n  const value = validateEvaluation(body);\n  return adminSettingsRepository.set('evaluation', value, admin.id);\n}\n\nexport async function getInterviewSettings() {\n  return adminSettingsRepository.get('interview');\n}\n\nexport async function updateInterviewSettings(body, admin) {\n  const value = validateInterview(body);\n  return adminSettingsRepository.set('interview', value, admin.id);\n}\n\nexport default { getEvaluationSettings, updateEvaluationSettings, getInterviewSettings, updateInterviewSettings };\n",
  "backend/services/adminStudents.service.js": "import { adminStudentsRepository } from '../repositories/adminStudents.repository.js';\nimport { adminAuditLogRepository } from '../repositories/adminAuditLog.repository.js';\nimport { adminNotificationsRepository } from '../repositories/adminNotifications.repository.js';\n\nexport async function listStudents({ search = '' } = {}) {\n  const students = await adminStudentsRepository.listStudents();\n  const q = search.trim().toLowerCase();\n  if (!q) return students;\n  return students.filter((s) =>\n    s.name?.toLowerCase().includes(q) ||\n    s.email?.toLowerCase().includes(q) ||\n    s.college?.toLowerCase().includes(q)\n  );\n}\n\nexport async function getStudentDetail(userId) {\n  const student = await adminStudentsRepository.getStudentDetail(userId);\n  if (!student) {\n    throw Object.assign(new Error('Student not found'), { statusCode: 404 });\n  }\n  return student;\n}\n\nexport async function setStudentActive(userId, isActive, admin) {\n  await adminStudentsRepository.setActive(userId, isActive);\n  adminAuditLogRepository.log({\n    adminId: admin.id,\n    adminName: admin.name,\n    action: isActive ? 'reactivate_student' : 'deactivate_student',\n    target: userId,\n  }).catch(() => {});\n  if (!isActive) {\n    adminNotificationsRepository.create({\n      title: 'Student deactivated',\n      message: `${admin.name} deactivated a student account`,\n      type: 'warning',\n    }).catch(() => {});\n  }\n}\n\nfunction csvEscape(value) {\n  const str = String(value ?? '');\n  if (/[\",\\n]/.test(str)) return `\"${str.replace(/\"/g, '\"\"')}\"`;\n  return str;\n}\n\nexport async function exportStudentsCsv() {\n  const students = await adminStudentsRepository.listStudents();\n  const header = ['Name', 'Email', 'College', 'Interviews', 'Average Score', 'Last Active', 'Status', 'Joined'];\n  const lines = [header.join(',')];\n  for (const s of students) {\n    lines.push([\n      s.name, s.email, s.college, s.interviews,\n      s.averageScore ?? '', s.lastActiveAt || '', s.isActive ? 'Active' : 'Deactivated', s.joinedAt || '',\n    ].map(csvEscape).join(','));\n  }\n  return lines.join('\\n');\n}\n\nexport default { listStudents, getStudentDetail, setStudentActive, exportStudentsCsv };\n",
};

let created = 0, updated = 0, unchanged = 0;
for (const [relPath, content] of Object.entries(files)) {
  const full = path.join(process.cwd(), relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  const exists = fs.existsSync(full);
  const prev = exists ? fs.readFileSync(full, 'utf8') : null;
  if (prev === content) { unchanged++; console.log('  = unchanged  ' + relPath); continue; }
  fs.writeFileSync(full, content, 'utf8');
  if (exists) { updated++; console.log('  ~ updated    ' + relPath); }
  else { created++; console.log('  + created    ' + relPath); }
}
console.log(`\nDone. ${created} created, ${updated} updated, ${unchanged} unchanged.`);